import bt, numpy as np
S=bt.signals(); R=bt.train_returns().astype(float); T=len(R)
print(T, R.shape)
sh=lambda x: x.mean()/x.std()*np.sqrt(252)
h=T*2//3
A,B=R[:h],R[h:]
fam=np.array([s.split('_')[0] for s in S])
for f in set(fam):
    m=fam==f; print(f, m.sum(), round(np.mean([sh(R[:,i]) for i in np.where(m)[0]]),3))
# candidate builders, fit on A, evaluate on B
def ew_family(X,f): return np.where(fam==f,1.0,0)
def topk(X,k):
    s=np.array([sh(X[:,i]) for i in range(X.shape[1])]); w=np.zeros(len(S)); idx=np.argsort(-np.abs(s))[:k]; w[idx]=np.sign(s[idx]); return w
def mv(X,lam):
    mu=X.mean(0); C=np.cov(X.T); C=(1-lam)*C+lam*np.diag(np.diag(C)); return np.linalg.solve(C,mu)
def ps(w,X): return sh(X@w)
cands={}
for f in ['tsmom','ma','hold']: cands['ew_'+f]=lambda X,f=f: ew_family(X,f)
cands['ew_trend']=lambda X:((fam=='tsmom')|(fam=='ma')).astype(float)
for k in [10,30,100,200]: cands[f'top{k}']=lambda X,k=k: topk(X,k)
for l in [0.5,0.9,0.99]: cands[f'mv{l}']=lambda X,l=l: mv(X,l)
for n,c in cands.items():
    print(n, round(ps(c(A),A),2), 'OOS', round(ps(c(A),B),2), '| reverse split', round(ps(c(B),A),2))
